package com.codegym.inotes.strategy;
import com.codegym.inotes.model.Note; import java.io.*; import java.nio.file.*; import java.util.*;
public class NoteFileStrategy implements NoteStrategy { private final Path file; public NoteFileStrategy(String path){file=Paths.get(path); } private List<Note> read()throws IOException{List<Note> out=new ArrayList<>();if(!Files.exists(file))return out;for(String line:Files.readAllLines(file)){String[] p=line.split("\\|",-1);if(p.length>=4)out.add(new Note(Integer.parseInt(p[0]),p[1],p[2],Integer.parseInt(p[3])));}return out;} private void write(List<Note> notes)throws IOException{if(file.getParent()!=null)Files.createDirectories(file.getParent());List<String> lines=new ArrayList<>();for(Note n:notes)lines.add(n.getId()+"|"+n.getTitle().replace("|"," ")+"|"+n.getContent().replace("|"," ")+"|"+n.getTypeId());Files.write(file,lines); } public void save(Note note)throws IOException{List<Note> all=read();if(note.getId()==0)note.setId(all.stream().mapToInt(Note::getId).max().orElse(0)+1);all.removeIf(n->n.getId()==note.getId());all.add(note);write(all);} public void delete(int id)throws IOException{List<Note> all=read();all.removeIf(n->n.getId()==id);write(all);} public List<Note> findAll()throws IOException{return read();} public List<Note> search(String k)throws IOException{String q=k==null?"":k.toLowerCase();return read().stream().filter(n->n.getTitle().toLowerCase().contains(q)||n.getContent().toLowerCase().contains(q)).toList();} }
